const STORE='wayvida-manual-journals-v2';
const TYPES=['General Journal','Adjustment Journal','Transfer Journal','Opening Balance','Correction Entry'];
const BUSINESS_PURPOSES={'Correction Entry':'Fix a mistake',Correction:'Fix a mistake','Adjustment Journal':'Update account balance',Adjustment:'Update account balance','Transfer Journal':'Move money between accounts','Opening Balance':'Add opening balances','General Journal':'Other adjustment','Opening Journal':'Add opening balances'};
