const EDITABLE_JOURNAL_STATUSES=['Draft','Pending Approval','Approved'];const canEditJournal=journal=>EDITABLE_JOURNAL_STATUSES.includes(journal.status);const isReversalJournal=journal=>!!journal.reversalOf||String(journal.reference||'').startsWith('Reversal of ');
