 const list=manual.filter(j=>!j.automatic).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
 const statusOptions=['All statuses','Draft','Pending Approval','Approved','Rejected','Posted','Reversed'],activeStatus=statusOptions.includes(status)?status:'All statuses',searchText=typeof query==='string'?query.trim().toLowerCase():'';
 const filtered=list.filter(j=>(activeStatus==='All statuses'||j.status===activeStatus)&&(creator==='All creators'||j.createdBy===creator)&&(journalType==='All'||j.type===journalType||(journalType==='Correction Entry'&&j.type==='Correction')||(journalType==='Adjustment Journal'&&j.type==='Adjustment'))&&(!fromDate||j.date>=fromDate)&&(!toDate||j.date<=toDate)&&[j.number,j.reference,j.narration,j.type,typeLabel(j.type,viewMode)].join(' ').toLowerCase().includes(searchText));
 const persist=rows=>{setManual(rows);saveManual(rows)};
