 const postToLedger=(record,source='Manual Journal',token='manual-journal:'+record.id)=>{const latest=readAccounts(seed),entry=journal(latest,{id:record.id,number:record.number,organizationId:localStorage.getItem('wayvida-demo-company')||'abc',branchId:record.lines[0]?.branch,role:'Admin',periodModule:'Accounting'},source,record.lines.map(line=>({account:line.account,debit:amount(line.debit),credit:amount(line.credit),branch:line.branch,costCentre:line.costCentre,description:line.description})),record.date,token);writeAccounts(latest);setAccountRevision(value=>value+1);return entry};
 const openCreate=(copy)=>{setForm(copy?{...copy,id:crypto.randomUUID(),number:'JV-2026-'+String(Date.now()).slice(-5),status:'Draft',createdAt:new Date().toISOString(),lines:copy.lines.map(l=>({...l,id:crypto.randomUUID()}))}:blank());setError('');setMode('create')};
 function validate(){const t=totals(form);if(!form.date||!form.narration.trim())return 'Date and notes are required.';if(form.date<'2026-04-01')return 'This accounting period is closed. Choose a date on or after 01 Apr 2026.';if(form.lines.some(l=>!l.account))return 'Select an account for every journal line.';if(form.lines.some(l=>amount(l.debit)&&amount(l.credit)))return 'A journal line cannot contain both debit and credit.';if(form.lines.some(l=>!amount(l.debit)&&!amount(l.credit)))return 'Enter a debit or credit amount for every journal line.';if(!t.debit||t.debit!==t.credit)return `Journal is not balanced. Difference ${money(Math.abs(t.debit-t.credit))}.`;const controlled=form.lines.find(l=>state.accounts.find(a=>a.code===l.account)?.controlAccount);if(controlled)return `${state.accounts.find(a=>a.code===controlled.account)?.name} is managed automatically by the system.`;return ''}
 function commit(targetStatus){const message=targetStatus==='Draft'?'':validate();if(message){setError(message);return}try{if(targetStatus==='Posted')assertOpenPeriod(form.date)}catch(error){setError(error.message);return}const now=new Date().toISOString(),base={...form,status:targetStatus,modifiedAt:now,...(targetStatus==='Pending Approval'?{submittedBy:'Admin',submittedAt:now}:{}),...(targetStatus==='Approved'?{approvedBy:'Admin',approvedAt:now}:{}),...(targetStatus==='Posted'?{postedBy:'Admin',postedAt:now}:{} )};try{const next=audited({...base,...(targetStatus==='Posted'?{ledgerJournalId:postToLedger(base).id}:{})},form.createdAt===form.modifiedAt?'Created':targetStatus,form.status);persist([next,...manual.filter(j=>j.id!==next.id)]);notify(`Journal ${targetStatus.toLowerCase()}`);setMode('list')}catch(reason){setError(reason.message)}}
 function action(j,next,payload={}){if(next==='Duplicate'){openCreate(j);return}if(j.automatic)return;try{if(next==='Posted')assertOpenPeriod(j.date);if(next==='Reverse')assertOpenPeriod(payload.date||new Date().toISOString().slice(0,10))}catch(error){setError(error.message);return}if(next==='Delete'){if(j.status==='Draft'){persist(manual.filter(x=>x.id!==j.id));notify('Draft journal deleted');return}if(isReversalJournal(j)){const source=manual.find(x=>x.id===j.reversalOf);const restored=source?{...source,status:'Approved',reversalJournalId:null,reversedAt:null,reversedBy:null,reversalReason:null,modifiedAt:new Date().toISOString()}:null;const nextRows=manual.filter(x=>x.id!==j.id).map(x=>restored&&x.id===restored.id?restored:x);persist(nextRows);setDetail(restored||null);notify('Reversal journal deleted; source journal restored for editing');return}return}if(next==='Reverse'){if(j.status!=='Posted'||j.reversalOf||j.reversalJournalId||String(j.reference||'').startsWith('Reversal of '))return;const stamp=new Date().toISOString(),base={...j,id:crypto.randomUUID(),number:'REV-'+j.number,date:payload.date||new Date().toISOString().slice(0,10),type:'Reversal',reference:'Reversal of '+j.number,narration:'Reversal: '+payload.reason,status:'Posted',createdAt:stamp,createdBy:'Admin',postedBy:'Admin',postedAt:stamp,reversalOf:j.id,reversalReason:payload.reason,lines:j.lines.map(l=>({...l,id:crypto.randomUUID(),debit:l.credit,credit:l.debit}))};try{const r=audited({...base,ledgerJournalId:postToLedger(base,'Journal Reversal','manual-reversal:'+j.id).id},'Reversed','Posted',payload.reason),original=audited({...j,status:'Reversed',reversalJournalId:r.id,reversedAt:stamp,reversedBy:'Admin',reversalReason:payload.reason},'Reversed','Posted',payload.reason),rows=[r,...manual.filter(x=>x.id!==j.id),original];persist(rows);setDetail(original);notify('Reversal journal posted')}catch(reason){setError(reason.message)}return}try{const stamp=new Date().toISOString(),base={...j,status:next,...(next==='Pending Approval'?{submittedBy:'Admin',submittedAt:stamp}:{}),...(next==='Approved'?{approvedBy:'Admin',approvedAt:stamp}:{}),...(next==='Rejected'?{rejectedBy:'Admin',rejectedAt:stamp}:{}),...(next==='Posted'?{postedBy:'Admin',postedAt:stamp}:{})},updated=audited({...base,...(next==='Posted'?{ledgerJournalId:postToLedger(base).id}:{})},next,j.status,payload.reason);persist(manual.map(x=>x.id===j.id?updated:x));setDetail(updated);notify(`Journal ${next.toLowerCase()}`)}catch(reason){setError(reason.message)}}
 if(mode==='create')return <JournalForm form={form} setForm={setForm} accounts={accounts} error={error} setError={setError} totals={totals(form)} onBack={()=>setMode('list')} onCommit={commit} onNavigate={onNavigate} editing={manual.some(j=>j.id===form.id)} viewMode={viewMode}/>;
